  FT["SG-H1925"] = {"id":"SG-H1925","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S383-2020?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（Armada Kraken 私人有限公司依第 13（4）条享有的豁免）公告 2020","en":"Income Tax (Armada Kraken Pte. Ltd. — Section 13(4) Exemption) Notification 2020","orig":"Income Tax (Armada Kraken Pte. Ltd. — Section 13(4) Exemption) Notification 2020","vi":"Thông báo Thuế thu nhập (Armada Kraken Pte. Ltd. — Miễn trừ theo Điều 13(4)) 2020","th":"ประกาศภาษีเงินได้ (Armada Kraken Pte. Ltd. — การยกเว้นตามมาตรา 13(4)) 2020","id":"Pemberitahuan Pajak Penghasilan (Armada Kraken Pte. Ltd. — Pembebasan menurut Pasal 13(4)) 2020","ms":"Pemberitahuan Cukai Pendapatan (Armada Kraken Pte. Ltd. — Pengecualian menurut Seksyen 13(4)) 2020"},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S383-2020","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H1925-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. This Notification is the Income Tax (Armada Kraken Pte. Ltd. — Section 13(4) Exemption) Notification 2020 and is deemed to have come into operation on 29 September 2014."}},{"id":"SG-H1925-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2.—(1) The interest payable by Armada Kraken Pte. Ltd. —\n(a)to the respective lenders mentioned in the first column of the following table;\n(b)in respect of the respective loan amounts mentioned in the second column of the table used to finance the conversion and refurbishment of the vessel, Armada Kraken, to a Floating Production Storage and Offloading vessel;\n(c)under the respective agreements mentioned in the third column of the table; and\n(d)that is due and payable during the respective periods mentioned in the fourth column of the table,\nis exempt from tax:\nFirst column\nSecond column\nThird column\nFourth column\nLender\nLoan amount\n(US$)\nAgreement\nPeriod (both dates inclusive)\nMaybank International Labuan Branch\n155,000,000\nBridging loan agreement dated 31 March 2014\n29 September 2014 to 18 December 2015\n183,080,000\nTerm loan agreement dated 7 July 2015\n18 December 2015 to 30 November 2017\nNational Bank of Abu Dhabi Pjsc, Labuan Branch\n109,840,000\nTerm loan agreement dated 7 July 2015\n18 December 2015 to 31 December 2016\n(2) Any interest rate swap payment made for the purpose of hedging against fluctuations in the rate of the interest mentioned in sub‑paragraph (1), and payable from 12 May 2016 to 18 December 2017 (both dates inclusive) by Armada Kraken Pte. Ltd. to Malayan Banking Berhad, is exempt from tax.\n(3) The exemptions under sub‑paragraphs (1) and (2) are subject to the terms and conditions specified in the letter of approval dated 24 March 2020 issued by the Ministry of Finance and addressed to Bumi Armada Berhad."}}],"pack":"sg-p24","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Armada Kraken Pte. Ltd. — Section 13(4) Exemption) Notification 2020","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H1926"] = {"id":"SG-H1926","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S510-2025?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（Ascott REIT (Europe) 私人有限公司依第 13（12）条享有的豁免）命令 2025","en":"Income Tax (Ascott REIT (Europe) Pte. Ltd. — Section 13(12) Exemption) Order 2025","orig":"Income Tax (Ascott REIT (Europe) Pte. Ltd. — Section 13(12) Exemption) Order 2025","vi":"Lệnh Thuế thu nhập (Ascott REIT (Europe) Pte. Ltd. — Miễn trừ theo Điều 13(12)) 2025","th":"คำสั่งภาษีเงินได้ (Ascott REIT (Europe) Pte. Ltd. — การยกเว้นตามมาตรา 13(12)) 2025","id":"Perintah Pajak Penghasilan (Ascott REIT (Europe) Pte. Ltd. — Pembebasan menurut Pasal 13(12)) 2025","ms":"Perintah Cukai Pendapatan (Ascott REIT (Europe) Pte. Ltd. — Pengecualian menurut Seksyen 13(12)) 2025"},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S510-2025","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H1926-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order is the Income Tax (Ascott REIT (Europe) Pte. Ltd. — Section 13(12) Exemption) Order 2025."}},{"id":"SG-H1926-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2.—(1) Subject to sub‑paragraph (3), interest income described in sub‑paragraph (2) received in Singapore by Ascott REIT (Europe) Pte. Ltd. (a company incorporated in Singapore) on or after 4 July 2025 from The Ascott (Europe) N.V. (a company incorporated in the Netherlands) and Ascott Holdings (France) SAS (a company incorporated in France), is exempt from tax.\n(2) Sub‑paragraph (1) applies to interest income originating from any rental and property‑related income (including capital gain derived from divestment of property) from the property named “La Clef Tour Eiffel Paris”, located at 83 avenue Kléber 75116 Paris, France.\n(3) The exemption in sub‑paragraph (1) is subject to the conditions specified in the letter from the Inland Revenue Authority of Singapore dated 4 July 2025 that is issued on behalf of the Minister for Finance and addressed to EY Corporate Advisors Pte. Ltd."}}],"pack":"sg-p24","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Ascott REIT (Europe) Pte. Ltd. — Section 13(12) Exemption) Order 2025","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H1927"] = {"id":"SG-H1927","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S448-2020?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（Ascott Residence 信托依第 13（12）条享有的豁免）命令 2020","en":"Income Tax (Ascott Residence Trust — Section 13(12) Exemption) Order 2020","orig":"Income Tax (Ascott Residence Trust — Section 13(12) Exemption) Order 2020","vi":"Lệnh Thuế thu nhập (Ascott Residence Trust — Miễn trừ theo Điều 13(12)) 2020","th":"คำสั่งภาษีเงินได้ (Ascott Residence Trust — การยกเว้นตามมาตรา 13(12)) 2020","id":"Perintah Pajak Penghasilan (Ascott Residence Trust — Pembebasan menurut Pasal 13(12)) 2020","ms":"Perintah Cukai Pendapatan (Ascott Residence Trust — Pengecualian menurut Seksyen 13(12)) 2020"},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S448-2020","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H1927-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order is the Income Tax (Ascott Residence Trust — Section 13(12) Exemption) Order 2020."}},{"id":"SG-H1927-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2.—(1) Interest income received in Singapore by Ascendas Hospitality Japan 2 Pte Ltd (a company incorporated in Singapore) from the branch in Japan of Ascendas Hospitality Japan 3 Pte Ltd (a company incorporated in Singapore) on or after 20 February 2020 is exempt from tax.\n(2) Trust distribution income received in Singapore by Perpetual (Asia) Limited (a company incorporated in Singapore) in its capacity as the trustee of Ascendas Hospitality Real Estate Investment Trust (a unit trust established in Singapore) from Ascendas Hospitality Australia Investment Fund No. 1 (an entity incorporated in Australia) on or after 20 February 2020 is exempt from tax.\n(3) The exemptions in sub‑paragraphs (1) and (2) are subject to the conditions specified in the letter of approval dated 20 February 2020 addressed to KPMG Services Pte. Ltd."}}],"pack":"sg-p24","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Ascott Residence Trust — Section 13(12) Exemption) Order 2020","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H1928"] = {"id":"SG-H1928","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S160-2022?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（Asia Liberty 私人有限公司等——第 13(4) 条豁免）公告 2022","en":"Income Tax (Asia Liberty Pte. Ltd., etc. — Section 13(4) Exemption) Notification 2022","orig":"Income Tax (Asia Liberty Pte. Ltd., etc. — Section 13(4) Exemption) Notification 2022","vi":"Thông báo Thuế thu nhập (Asia Liberty Pte. Ltd., etc. — Miễn trừ theo Điều 13(4)) 2022","th":"ประกาศภาษีเงินได้ (Asia Liberty Pte. Ltd., etc. — การยกเว้นตามมาตรา 13(4)) 2022","id":"Pemberitahuan Pajak Penghasilan (Asia Liberty Pte. Ltd., etc. — Pembebasan menurut Pasal 13(4)) 2022","ms":"Pemberitahuan Cukai Pendapatan (Asia Liberty Pte. Ltd., etc. — Pengecualian menurut Seksyen 13(4)) 2022"},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S160-2022","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H1928-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. This Notification is the Income Tax (Asia Liberty Pte. Ltd., etc. — Section 13(4) Exemption) Notification 2022 and is deemed to have come into operation on 26 February 2021."}},{"id":"SG-H1928-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2.—(1) The arrangement fee of USD 468,000 paid on 26 February 2021 by Asia Liberty Pte. Ltd. and Asia Inspire Pte. Ltd. to Credit Suisse AG for a loan granted under a loan agreement dated 24 February 2021 to refinance the acquisition of 2 Singapore‑flagged vessels “Asia Liberty” and “Asia Inspire” is exempt from tax.\n(2) The exemption under sub‑paragraph (1) is subject to the terms and conditions specified in the letter of approval dated 25 February 2022 issued by the Ministry of Finance and addressed to Asia Liberty Pte. Ltd. and Asia Inspire Pte. Ltd."}}],"pack":"sg-p24","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Asia Liberty Pte. Ltd., etc. — Section 13(4) Exemption) Notification 2022","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H1929"] = {"id":"SG-H1929","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S313-2024?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（依第 3A 条转授职能——建设局）公告 2024","en":"Income Tax (Assignment of Functions under Section 3A — Building and Construction Authority) Notification 2024","orig":"Income Tax (Assignment of Functions under Section 3A — Building and Construction Authority) Notification 2024","vi":"Thông báo Thuế thu nhập (Chuyển giao chức năng theo Điều 3A — Cơ quan Xây dựng và Kiến trúc) 2024","th":"ประกาศภาษีเงินได้ (การมอบหมายหน้าที่ตามมาตรา 3A — หน่วยงานอาคารและการก่อสร้าง) 2024","id":"Pemberitahuan Pajak Penghasilan (Pelimpahan Fungsi menurut Pasal 3A — Otoritas Bangunan dan Konstruksi) 2024","ms":"Pemberitahuan Cukai Pendapatan (Penyerahan Fungsi menurut Seksyen 3A — Pihak Berkuasa Bangunan dan Pembinaan) 2024"},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S313-2024","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H1929-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. This Notification is the Income Tax (Assignment of Functions under Section 3A — Building and Construction Authority) Notification 2024 and comes into operation on 12 April 2024."}},{"id":"SG-H1929-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Assignment of functions"},"text":{"en":"2. The Minister assigns to the Building and Construction Authority the following powers of the Minister under the Act:\n(a)the power to vary a condition, mentioned in section 18C(2A) of the Act;\n(b)the power to approve an application, mentioned in section 18C(2B) of the Act;\n(c)the power to impose conditions, mentioned in section 18C(2D) of the Act;\n(d)the power to substitute or add a person or trade or business, mentioned in section 18C(2E) of the Act;\n(e)the power to approve an application, mentioned in section 18C(2F) of the Act;\n(f)the power to revoke an approval, mentioned in section 18C(8) of the Act;\n(g)the power to determine the form and manner in which, and time within which, records of an approved construction or approved renovation must be maintained and delivered to the Building and Construction Authority, mentioned in section 18C(11) of the Act."}}],"pack":"sg-p24","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Assignment of Functions under Section 3A — Building and Construction Authority) Notification 2024","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H1930"] = {"id":"SG-H1930","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S314-2024?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（依第 3A 条转授职能——经济发展局）公告 2024","en":"Income Tax (Assignment of Functions under Section 3A — Economic Development Board) Notification 2024","orig":"Income Tax (Assignment of Functions under Section 3A — Economic Development Board) Notification 2024","vi":"Thông báo Thuế thu nhập (Chuyển giao chức năng theo Điều 3A — Ủy ban Phát triển Kinh tế) 2024","th":"ประกาศภาษีเงินได้ (การมอบหมายหน้าที่ตามมาตรา 3A — คณะกรรมการพัฒนาเศรษฐกิจ) 2024","id":"Pemberitahuan Pajak Penghasilan (Pelimpahan Fungsi menurut Pasal 3A — Dewan Pengembangan Ekonomi) 2024","ms":"Pemberitahuan Cukai Pendapatan (Penyerahan Fungsi menurut Seksyen 3A — Lembaga Pembangunan Ekonomi) 2024"},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S314-2024","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H1930-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. This Notification is the Income Tax (Assignment of Functions under Section 3A — Economic Development Board) Notification 2024 and comes into operation on 12 April 2024."}},{"id":"SG-H1930-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Assignment of functions"},"text":{"en":"2.—(1) The Minister assigns to the Economic Development Board —\n(a)the powers of the Minister under the Act specified in sub‑paragraph (2); and\n(b)the powers of the Minister under the subsidiary legislation specified in sub‑paragraph (3).\n(2) For the purposes of sub‑paragraph (1)(a), the powers are —\n(a)the power to approve a not‑for‑profit organisation, mentioned in section 13R(2) of the Act;\n(b)the powers to impose conditions and to specify the period of the approval, mentioned in section 13R(3) of the Act;\n(c)the power to extend the period of the approval, mentioned in section 13R(4) of the Act;\n(ca)the power to approve an innovation cost-sharing agreement for the purposes of section 14EB(1) of the Act;\n[S 786/2025 wef 09/12/2025]\n(cb)the powers to impose conditions when approving an innovation cost-sharing agreement and to specify the period during which any payment made under the innovation cost-sharing agreement is allowed a deduction, mentioned in section 14EB(2) of the Act;\n[S 786/2025 wef 09/12/2025]\n(cc)the power to specify requirements that must be satisfied to approve an innovation cost-sharing agreement, mentioned in section 14EB(3) of the Act;\n[S 786/2025 wef 09/12/2025]\n(d)the power to vary a condition, mentioned in section 18C(2A) of the Act;\n(e)the power to approve an application, mentioned in section 18C(2B) of the Act;\n(f)the power to impose conditions, mentioned in section 18C(2D) of the Act;\n(g)the power to substitute or add a person or trade or business, mentioned in section 18C(2E) of the Act;\n(h)the power to approve an application, mentioned in section 18C(2F) of the Act;\n(i)the power to revoke an approval, mentioned in section 18C(8) of the Act;\n(j)the power to determine the form and manner in which, and time within which, records of an approved construction or approved renovation must be maintained and delivered to the Economic Development Board, mentioned in section 18C(11) of the Act;\n(k)the powers to waive a requirement and to impose conditions, mentioned in section 19B(2B) of the Act;\n(l)the powers to make a determination and to give written notice of the determination, mentioned in section 19B(2BA) of the Act;\n(m)the powers mentioned in sub‑paragraphs (k) and (l) as applied by section 36(1B) of the Act;\n(n)the powers to approve a Finance and Treasury Centre and to impose conditions, mentioned in section 43E(2A) of the Act;\n(na)the power to specify that the concessionary rate of tax of 8% or 10% mentioned in section 43E(1A)(c) of the Act applies to the income of a company mentioned in section 43E(1) of the Act in relation to its Finance and Treasury Centre that is approved on or after 17 February 2024;\n[S 763/2025 wef 12/04/2024]\n(nb)the powers to substitute the concessionary rate of tax applicable to a company’s approved Finance and Treasury Centre with 8% or 10% and to specify the date from which the substituted rate applies, mentioned in section 43E(1B) of the Act read with section 43E(1A)(d) of the Act;\n[S 763/2025 wef 28/11/2025]\n(o)the powers to approve an aircraft leasing company and to impose conditions, mentioned in section 43N(2) of the Act;\n(oa)the power to specify that the concessionary rate of tax of 8% or 10% mentioned in section 43N(1)(c) of the Act applies to the income of an aircraft leasing company that is approved on or after 17 February 2024;\n[S 763/2025 wef 12/04/2024]\n(ob)the powers to substitute the concessionary rate of tax applicable to an approved aircraft leasing company with 8% or 10% and to specify the date from which the substituted rate applies, mentioned in section 43N(1D) of the Act read with section 43N(1)(d) of the Act;\n[S 763/2025 wef 28/11/2025]\n(p)the power to extend the period during which the income of an approved aircraft leasing company is taxed at a concessionary rate, mentioned in section 43N(3) of the Act;\n(q)the powers mentioned in sub‑paragraphs (o) and (p), as applied by section 36(1A) of the Act;\n(r)the power to approve an aircraft leasing company for the purpose of section 43O(1) of the Act;\n(s)the powers to approve an aircraft investment manager and to impose conditions, mentioned in section 43O(3) of the Act;\n(t)the powers to approve a company as an approved company and to specify terms and conditions, mentioned in section 43X(2) of the Act;\n(u)the powers to specify an initial tax relief period for an approved company, to specify a commencement date for the initial tax relief period, to extend the tax relief period for a further period or periods and to determine the period or periods of extension, mentioned in section 43X(3) of the Act;\n(v)the power to specify the base rate for determining the concessionary rate of tax for an approved company, mentioned in section 43X(5)(b) of the Act;\n[S 763/2025 wef 12/04/2024]\n[S 575/2025 wef 01/09/2025]\n(w)the power to specify the rate increase for an approved company mentioned in section 43X(6) of the Act, for the purpose of section 43X(5)(d) of the Act;\n[S 763/2025 wef 12/04/2024]\n[S 575/2025 wef 01/09/2025]\n(wa)the powers to substitute the base rate applicable to an approved company with 5%, 10% or 15% and to specify the date from which the substituted base rate applies, mentioned in section 43X(6A) of the Act read with section 43X(5)(c) of the Act;\n[S 763/2025 wef 28/11/2025]\n(wb)the powers to determine the period within which an application under section 92K(3) of the Act must be made, and to require any information and documents to accompany the application, mentioned in section 92K(4) of the Act;\n[S 786/2025 wef 09/12/2025]\n(wc)the powers to approve a company as an approved company for the purposes of section 92K of the Act and to impose conditions, mentioned in section 92K(6) of the Act;\n[S 786/2025 wef 09/12/2025]\n(wd)the power to approve the nomination of the eligible subsidiaries of a company making an application under section 92K(3) of the Act, mentioned in section 92K(15)(a) of the Act;\n[S 786/2025 wef 09/12/2025]\n(we)the power to approve the nomination of the eligible subsidiaries of an approved company, mentioned in section 92K(16) of the Act;\n[S 786/2025 wef 09/12/2025]\n(wf)the power to determine the date from which the approval of a nominee under section 92K(15)(a) of the Act is effective, mentioned in section 92K(17) of the Act;\n[S 786/2025 wef 09/12/2025]\n(wg)the power to determine the date from which the approval of a nominee under section 92K(16) of the Act is effective, mentioned in section 92K(18) of the Act;\n[S 786/2025 wef 09/12/2025]\n(wh)the powers to approve another eligible subsidiary of an approved company as a replacement nominee, and to determine the period in which an application for approval may be made, mentioned in section 92K(22) of the Act;\n[S 786/2025 wef 09/12/2025]\n(wi)the power to determine the date from which the approval of a replacement nominee is effective, mentioned in section 92K(23) of the Act;\n[S 786/2025 wef 09/12/2025]\n(wj)the power to require any information and documents to accompany an application under section 92K(15), (16) or (22) of the Act, mentioned in section 92K(25) of the Act;\n[S 786/2025 wef 09/12/2025]\n(x)the power to approve an application and issue a letter of award to a company, mentioned in section 93B(4) of the Act;\n[S 575/2025 wef 01/09/2025]\n(y)the power to specify any matter in a letter of award, mentioned in section 93B(5) of the Act read with section 93B(6) and (7) of the Act;\n[S 575/2025 wef 01/09/2025]\n(z)the power to issue a single letter of award to a company for 2 or more qualifying activities, mentioned in section 93B(10) of the Act;\n[S 575/2025 wef 01/09/2025]\n(za)the power to amend any matter or correct any error in a letter of award, mentioned in section 93B(12) and (13) of the Act;\n[S 575/2025 wef 01/09/2025]\n(zb)the power to extend the claim period for an awardee company to make an application under section 93B(15) of the Act and to require any information and documents to accompany the application, mentioned in section 93B(16) of the Act;\n[S 145/2026 wef 01/04/2026]\n(zba)the power to give an awardee company an amount of RICs by a letter of confirmation to the company, mentioned in section 93B(17) of the Act;\n[S 145/2026 wef 01/04/2026]\n(zbb)the power to amend any matter stated in a letter of confirmation, mentioned in section 93B(20A) of the Act;\n[S 145/2026 wef 01/04/2026]\n(zc)the power to specify the date for any amount of RICs given to an awardee company to be paid to the company pursuant to an election made by the company, in accordance with any regulations made under section 93B(51) of the Act, read with section 93B(23)(a) of the Act;\n[S 575/2025 wef 01/09/2025]\n(zd)the power to require an awardee company to show cause why a matter specified in its letter of award should not be amended, or its letter of award should not be revoked, mentioned in section 93B(34) of the Act;\n[S 575/2025 wef 01/09/2025]\n(ze)the power to amend a matter in a letter of award or revoke a letter of award of an awardee company, mentioned in section 93B(35) of the Act;\n[S 575/2025 wef 01/09/2025]\n(zf)the power to specify any date for an amendment or the revocation of a letter of award of an awardee company, mentioned in section 93B(37) of the Act;\n[S 575/2025 wef 01/09/2025]\n(zg)the power to approve an application mentioned in section 93B(44) of the Act, for the purposes of section 93B(43) of the Act; and\n[S 575/2025 wef 01/09/2025]\n(zh)the power to approve an application made by an awardee company for an amount of RICs given to it to be used to offset any due tax of another company in the same group as the awardee company, in accordance with any regulations made under section 93B(51) of the Act, read with section 93B(46) of the Act.\n[S 575/2025 wef 01/09/2025]\n(3) For the purposes of sub‑paragraph (1)(b), the subsidiary legislation is —\n(a)the Income Tax (Concessionary Rate of Tax for Approved Finance and Treasury Centre) Regulations 2017 (G.N. No. S 88/2017);\n[S 145/2026 wef 01/04/2026]\n(b)the Income Tax (Concessionary Rate of Tax on Dividends — Aircraft Leasing Company) Order 2020 (G.N. No. S 673/2020); and\n[S 145/2026 wef 01/04/2026]\n(c)the Income Tax (Refundable Investment Credits) Regulations 2025 (G.N. No. S 577/2025).\n[S 145/2026 wef 01/04/2026]"}}],"pack":"sg-p24","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Assignment of Functions under Section 3A — Economic Development Board) Notification 2024","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H1931"] = {"id":"SG-H1931","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S315-2024?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（依第 3A 条转授职能——新加坡企业发展局）公告 2024","en":"Income Tax (Assignment of Functions under Section 3A — Enterprise Singapore Board) Notification 2024","orig":"Income Tax (Assignment of Functions under Section 3A — Enterprise Singapore Board) Notification 2024","vi":"Thông báo Thuế thu nhập (Chuyển giao chức năng theo Điều 3A — Ủy ban Doanh nghiệp Singapore) 2024","th":"ประกาศภาษีเงินได้ (การมอบหมายหน้าที่ตามมาตรา 3A — คณะกรรมการ Enterprise Singapore) 2024","id":"Pemberitahuan Pajak Penghasilan (Pelimpahan Fungsi menurut Pasal 3A — Dewan Enterprise Singapore) 2024","ms":"Pemberitahuan Cukai Pendapatan (Penyerahan Fungsi menurut Seksyen 3A — Lembaga Enterprise Singapore) 2024"},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S315-2024","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H1931-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. This Notification is the Income Tax (Assignment of Functions under Section 3A — Enterprise Singapore Board) Notification 2024 and comes into operation on 12 April 2024."}},{"id":"SG-H1931-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Assignment of functions"},"text":{"en":"2.—(1) The Minister assigns to the Enterprise Singapore Board —\n(a)the powers of the Minister under the Act specified in sub‑paragraph (2); and\n(b)the powers of the Minister under the subsidiary legislation specified in sub‑paragraph (3).\n(2) For the purposes of sub‑paragraph (1)(a), the powers are —\n(a)the power to specify the period during which income of an approved venture company is exempt from tax, mentioned in section 13G(2A)(b) and (2BA)(a) and (b) of the Act;\n(b)the powers to approve a venture company and impose conditions, mentioned in section 13G(2C) of the Act;\n(c)the powers mentioned in sub‑paragraphs (a) and (b), as applied by section 36(1A) of the Act;\n(d)the power to approve a firm or company for the purpose of section 14B(1) of the Act;\n(e)the power to approve a trade fair or trade exhibition held in Singapore for the purpose of section 14B(2)(a)(ii) of the Act;\n(f)the power to approve expenses for the purpose of section 14B(2)(aa) of the Act;\n(g)the power to approve a trade fair or trade exhibition for the purpose of section 14B(2)(ab) of the Act;\n(h)the power to approve expenses for the purposes of section 14B(2)(ac) of the Act;\n(i)the power to approve an overseas trade office for the purpose of section 14B(2)(b) of the Act;\n(j)the power to approve a marketing project for the purpose of section 14B(2)(c) of the Act;\n(k)the power to approve any certification of goods and services for the purposes of section 14B(2AC)(b) of the Act;\n(l)the power to specify the maximum amount of expenditure or any item thereof, mentioned in section 14B(3) of the Act;\n(m)the power to approve the maximum number of employees for the purpose of section 14B(4)(b)(ii) of the Act;\n(n)the power to approve the maximum number of years after the date of establishment of an approved overseas trade office, for the purpose of section 14B(4)(c)(iv) of the Act;\n(o)the powers to allow a deduction of expenses and to impose conditions, mentioned in section 14B(4A) and (5) of the Act;\n(p)the power to approve expenses for the purpose of paragraph (a) of the definition of “market development expenditure” in section 14B(11) of the Act;\n(q)the power to approve media for the purpose of paragraph (b) of the definition of “market development expenditure” in section 14B(11) of the Act;\n(r)the power to approve promotion campaigns for the purpose of paragraph (c) of the definition of “market development expenditure” in section 14B(11) of the Act;\n(s)the power to approve expenses for the purpose of paragraph (d) of the definition of “market development expenditure” in section 14B(11) of the Act;\n(t)the power to approve a person for the purpose of paragraph (d) of the definition of “market development expenditure” in section 14B(11) of the Act;\n(u)the power to approve expenses for the purpose of paragraph (e) of the definition of “market development expenditure” in section 14B(11) of the Act;\n(v)the power to approve an investment project for the purpose of section 14H(1) of the Act;\n(w)the power to approve a firm or company for the purpose of section 14H(1) of the Act;\n(x)the powers to specify the maximum investment development expenditure and to impose conditions, mentioned in section 14H(2) of the Act;\n(y)the power to approve the maximum number of employees for the purpose of section 14H(3)(a)(ii) of the Act;\n(z)the powers to allow a deduction and to impose conditions, mentioned in section 14H(4) of the Act;\n(za)the power to approve an investment overseas, mentioned in paragraph (a)(ii) of the definition of “investment development expenditure” in section 14H(7) of the Act;\n(zb)the power to approve a firm or company, mentioned in section 14I(5) of the Act;\n(zc)the power to impose conditions, mentioned in section 14I(6) of the Act;\n(zd)the power to specify the salary expenditure, mentioned in section 14I(7) of the Act;\n(ze)the power to specify the maximum amount of expenditure, mentioned in section 14I(8) of the Act;\n(zf)the powers to allow a deduction and to impose conditions, mentioned in section 14I(11) of the Act;\n(zg)the power to approve an entity as an overseas establishment of a firm or company, mentioned in paragraph (c) of the definition of “overseas establishment” in section 14I(18) of the Act;\n(zh)the powers to waive requirements and to impose conditions, mentioned in section 37N(8) of the Act;\n(zi)the power to determine the form and manner in which, and the time within which, the relevant records of qualifying investment must be maintained and delivered to the Enterprise Singapore Board, mentioned in section 37N(11) of the Act;\n(zj)the power to waive the requirement mentioned in paragraph (b) of the definition of “qualifying start‑up company” in section 37N(12) of the Act;\n(zk)the power to specify an activity mentioned in paragraph (e) of the definition of “qualifying start‑up company” in section 37N(12) of the Act;\n(zl)the power to specify prescribed qualifying transactions in prescribed commodities, and the prescribed commodities, for an approved global trading company, mentioned in section 43I(1)(a)(i) of the Act;\n(zm)the power to specify prescribed qualifying structured commodity financing activities, prescribed treasury activities and prescribed advisory services in relation to mergers and acquisitions, for an approved global trading company, mentioned in section 43I(1)(a)(iii) of the Act;\n(zn)the power to specify prescribed qualifying structured commodity financing activities, prescribed treasury activities and prescribed advisory services in relation to mergers and acquisitions, for an approved qualifying company, mentioned in section 43I(1)(b) of the Act;\n(zo)the powers to approve a global trading company as an approved global trading company, and to impose conditions, mentioned in section 43I(1AB) of the Act;\n(zoa)the powers to substitute the rate of tax applicable to an approved global trading company with 5%, 10% or 15% and to specify the date from which the substituted rate of tax applies, mentioned in section 43I(1AC) of the Act read with section 43I(1AA)(d) of the Act;\n[S 764/2025 wef 12/04/2024]\n(zp)the power to approve a fund management company, mentioned in section 43V(2) of the Act;\n(zq)the power to impose conditions, mentioned in section 43V(3) of the Act;\n(zr)the powers to specify the period of approval and to extend the period, mentioned in section 43V(4) of the Act;\n(zs)the powers to approve a company as an approved company and to specify terms and conditions, mentioned in section 43X(2) of the Act;\n(zt)the powers to specify an initial tax relief period for an approved company, to specify a commencement date for the initial tax relief period, to extend the tax relief period for a further period or periods and to determine the period or periods of extension, mentioned in section 43X(3) of the Act;\n(zu)the power to specify the base rate for determining the concessionary rate of tax for an approved company, mentioned in section 43X(5)(b) of the Act;\n[S 764/2025 wef 12/04/2024]\n[S 576/2025 wef 01/09/2025]\n(zv)the power to specify the rate increase for an approved company mentioned in section 43X(6) of the Act, for the purpose of section 43X(5)(d) of the Act;\n[S 764/2025 wef 12/04/2024]\n[S 576/2025 wef 01/09/2025]\n(zva)the powers to substitute the base rate applicable to an approved company with 5%, 10% or 15% and to specify the date from which the substituted base rate applies, mentioned in section 43X(6A) of the Act read with section 43X(5)(c) of the Act;\n[S 764/2025 wef 28/11/2025]\n(zvb)the powers to determine the period within which an application under section 92K(3) of the Act must be made, and to require any information and documents to accompany the application, mentioned in section 92K(4) of the Act;\n[S 787/2025 wef 09/12/2025]\n(zvc)the powers to approve a company as an approved company for the purposes of section 92K of the Act and to impose conditions, mentioned in section 92K(6) of the Act;\n[S 787/2025 wef 09/12/2025]\n(zvd)the power to approve the nomination of the eligible subsidiaries of a company making an application under section 92K(3) of the Act, mentioned in section 92K(15)(a) of the Act;\n[S 787/2025 wef 09/12/2025]\n(zve)the power to approve the nomination of the eligible subsidiaries of an approved company, mentioned in section 92K(16) of the Act;\n[S 787/2025 wef 09/12/2025]\n(zvf)the power to determine the date from which the approval of a nominee under section 92K(15)(a) of the Act is effective, mentioned in section 92K(17) of the Act;\n[S 787/2025 wef 09/12/2025]\n(zvg)the power to determine the date from which the approval of a nominee under section 92K(16) of the Act is effective, mentioned in section 92K(18) of the Act;\n[S 787/2025 wef 09/12/2025]\n(zvh)the powers to approve another eligible subsidiary of an approved company as a replacement nominee, and to determine the period in which an application for approval may be made, mentioned in section 92K(22) of the Act;\n[S 787/2025 wef 09/12/2025]\n(zvi)the power to determine the date from which the approval of a replacement nominee is effective, mentioned in section 92K(23) of the Act;\n[S 787/2025 wef 09/12/2025]\n(zvj)the power to require any information and documents to accompany an application under section 92K(15), (16) or (22) of the Act, mentioned in section 92K(25) of the Act;\n[S 787/2025 wef 09/12/2025]\n(zw)the power to approve an application and issue a letter of award to a company, mentioned in section 93B(4) of the Act;\n[S 576/2025 wef 01/09/2025]\n(zx)the power to specify any matter in a letter of award, mentioned in section 93B(5) of the Act read with section 93B(6) and (7) of the Act;\n[S 576/2025 wef 01/09/2025]\n(zy)the power to issue a single letter of award to a company for 2 or more qualifying activities, mentioned in section 93B(10) of the Act;\n[S 576/2025 wef 01/09/2025]\n(zz)the power to amend any matter or correct any error in a letter of award, mentioned in section 93B(12) and (13) of the Act;\n[S 576/2025 wef 01/09/2025]\n(zza)the power to extend the claim period for an awardee company to make an application under section 93B(15) of the Act and to require any information and documents to accompany the application, mentioned in section 93B(16) of the Act;\n[S 146/2026 wef 01/04/2026]\n(zzaa)the power to give an awardee company an amount of RICs by a letter of confirmation to the company, mentioned in section 93B(17) of the Act;\n[S 146/2026 wef 01/04/2026]\n(zzab)the power to amend any matter stated in a letter of confirmation, mentioned in section 93B(20A) of the Act;\n[S 146/2026 wef 01/04/2026]\n(zzb)the power to specify the date for any amount of RICs given to an awardee company to be paid to the company pursuant to an election made by the company, in accordance with any regulations made under section 93B(51) of the Act, read with section 93B(23)(a) of the Act;\n[S 576/2025 wef 01/09/2025]\n(zzc)the power to require an awardee company to show cause why a matter specified in its letter of award should not be amended, or its letter of award should not be revoked, mentioned in section 93B(34) of the Act;\n[S 576/2025 wef 01/09/2025]\n(zzd)the power to amend a matter in a letter of award or revoke a letter of award of an awardee company, mentioned in section 93B(35) of the Act;\n[S 576/2025 wef 01/09/2025]\n(zze)the power to specify any date for an amendment or the revocation of a letter of award of an awardee company, mentioned in section 93B(37) of the Act;\n[S 576/2025 wef 01/09/2025]\n(zzf)the power to approve an application mentioned in section 93B(44) of the Act, for the purposes of section 93B(43) of the Act; and\n[S 576/2025 wef 01/09/2025]\n(zzg)the power to approve an application made by an awardee company for an amount of RICs given to it to be used to offset any due tax of another company in the same group as the awardee company, in accordance with any regulations made under section 93B(51) of the Act, read with section 93B(46) of the Act.\n[S 576/2025 wef 01/09/2025]\n(3) For the purposes of sub‑paragraph (1)(b), the subsidiary legislation is —\n(a)the Income Tax (Exemption of Income of Approved Venture Company) Regulations (Rg 22);\n(b)the Income Tax (Concessionary Rate of Tax for Approved Qualifying Companies) Regulations 2013 (G.N. No. S 731/2013);\n[S 146/2026 wef 01/04/2026]\n(c)the Income Tax (Concessionary Rate of Tax for Global Trading Companies) Regulations 2016 (G.N. No. S 341/2016); and\n[S 146/2026 wef 01/04/2026]\n(d)the Income Tax (Refundable Investment Credits) Regulations 2025 (G.N. No. S 577/2025).\n[S 146/2026 wef 01/04/2026]"}}],"pack":"sg-p24","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Assignment of Functions under Section 3A — Enterprise Singapore Board) Notification 2024","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H1932"] = {"id":"SG-H1932","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S316-2024?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（依第 3A 条转授职能——新加坡海事及港务管理局）公告 2024","en":"Income Tax (Assignment of Functions under Section 3A — Maritime and Port Authority of Singapore) Notification 2024","orig":"Income Tax (Assignment of Functions under Section 3A — Maritime and Port Authority of Singapore) Notification 2024","vi":"Thông báo Thuế thu nhập (Chuyển giao chức năng theo Điều 3A — Cơ quan Hàng hải và Cảng Singapore) 2024","th":"ประกาศภาษีเงินได้ (การมอบหมายหน้าที่ตามมาตรา 3A — หน่วยงานการเดินเรือและท่าเรือสิงคโปร์) 2024","id":"Pemberitahuan Pajak Penghasilan (Pelimpahan Fungsi menurut Pasal 3A — Otoritas Maritim dan Pelabuhan Singapura) 2024","ms":"Pemberitahuan Cukai Pendapatan (Penyerahan Fungsi menurut Seksyen 3A — Pihak Berkuasa Maritim dan Pelabuhan Singapura) 2024"},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S316-2024","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H1932-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. This Notification is the Income Tax (Assignment of Functions under Section 3A — Maritime and Port Authority of Singapore) Notification 2024 and comes into operation on 12 April 2024."}},{"id":"SG-H1932-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Assignment of functions"},"text":{"en":"2.—(1) The Minister assigns to the Maritime and Port Authority of Singapore —\n(a)the powers of the Minister under the Act specified in sub‑paragraph (2); and\n(b)the powers of the Minister under the subsidiary legislation specified in sub‑paragraph (3).\n(2) For the purposes of sub‑paragraph (1)(a), the powers are —\n(aa)the power to approve a shipping financing arrangement enterprise for the purposes of section 13(5) of the Act;\n[S 788/2025 wef 09/12/2025]\n(ab)the power to specify conditions of approval of a shipping financing arrangement enterprise, mentioned in section 13(5A)(a) of the Act;\n[S 788/2025 wef 09/12/2025]\n(ac)the powers to specify the period of the approval and to extend the period of the approval, mentioned in section 13(5A)(b) of the Act;\n[S 788/2025 wef 09/12/2025]\n(ad)the power to approve a company, a partnership or a registered business trust as an approved special purpose vehicle of a shipping financing arrangement enterprise for the purposes of section 13(5), (5A) and (5C) of the Act;\n[S 788/2025 wef 09/12/2025]\n(a)the power to approve a company as an approved international shipping enterprise under section 13E(1B) of the Act, and to impose conditions on the approval;\n(b)the powers to specify the period of the approval and to extend the period of the approval under section 13E(2) of the Act;\n(c)the power to determine qualifying conditions for the purposes of section 13E(2)(a) of the Act, mentioned in section 13E(2)(b) of the Act;\n(d)the powers to approve a partnership or company as a qualifying special purpose vehicle and to impose conditions, mentioned in section 13E(8) of the Act;\n(e)the power to approve a shipping investment enterprise or a related party of an approved shipping investment enterprise, mentioned in section 13P(2) of the Act;\n(f)the powers to specify conditions to which an approval is subject, to specify the period for which the approval is granted, to extend the period for which the approval is granted and to specify the period of the extension, mentioned in section 13P(3) of the Act;\n(g)the power to specify the period during which income is exempt from tax, mentioned in section 13P(4) of the Act;\n(h)the power to approve an entity for the purpose of paragraph (b) of the definition of “related party” in section 13P(20) of the Act;\n(i)the powers mentioned in sub‑paragraphs (e) to (h) as applied by section 36(1A) of the Act;\n(j)the power to approve a shipping investment enterprise for the purpose of section 43L(1) of the Act;\n(k)the powers to approve a shipping investment manager as an approved shipping investment manager and to impose conditions, mentioned in section 43L(3) of the Act;\n(l)the power to extend the period of the approval, mentioned in section 43L(4A) of the Act;\n(m)the power to specify the rate of tax, mentioned in section 43P(1) of the Act;\n(n)the power to approve a container investment enterprise or a related party of an approved container investment enterprise, mentioned in section 43P(3) of the Act;\n(o)the power to specify conditions, mentioned in section 43P(4) of the Act;\n(p)the power to specify a period during which income is subject to the applicable concessionary tax rate, mentioned in section 43P(5) of the Act;\n(q)the power to approve an entity mentioned in paragraph (b) of the definition of “related party” in section 43P(7) of the Act;\n(r)the powers mentioned in sub‑paragraphs (m) to (q) as applied by section 36(1A) of the Act;\n(s)the powers to approve a container investment manager as an approved container investment manager and to impose conditions, mentioned in section 43Q(3) of the Act;\n(t)the powers to specify the period of the approval and to extend the period of the approval, mentioned in section 43Q(4A) of the Act;\n(u)the power to impose conditions, mentioned in section 43U(2) of the Act;\n(v)the power to approve for a company shipping-related support services, mentioned in section 43U(2A) and (5B) of the Act;\n(w)the power to approve for a company accounts other than audited accounts, mentioned in section 43U(4)(a) and (5I)(a) of the Act;\n(x)the powers to extend the period of approval of an approved company and to impose conditions, mentioned in section 43U(5A) of the Act;\n(y)the power to determine the form and manner by which, and the time within which, an election may be made, mentioned in section 43U(5G) of the Act;\n[S 788/2025 wef 09/12/2025]\n(z)the power to determine the particulars that must accompany an election, mentioned in section 43U(5G) of the Act;\n[S 788/2025 wef 09/12/2025]\n(za)the powers to approve an SPV of an approved company and impose conditions, mentioned in section 43U(5L)(a) of the Act;\n[S 788/2025 wef 09/12/2025]\n(zb)the powers to approve for an SPV shipping-related support services, mentioned in section 43U(5L)(b) of the Act;\n[S 788/2025 wef 09/12/2025]\n(zc)the power to specify the period of approval of an SPV, mentioned in section 43U(5L)(c) of the Act;\n[S 788/2025 wef 09/12/2025]\n(zd)the power to approve for an approved SPV accounts other than audited accounts, mentioned in section 43U(5O)(c) of the Act; and\n[S 788/2025 wef 09/12/2025]\n(ze)the power to extend the period of approval of an approved SPV, approve for the approved SPV shipping-related support services and impose conditions, mentioned in section 43U(5Q) of the Act.\n[S 788/2025 wef 09/12/2025]\n(3) For the purposes of sub‑paragraph (1)(b), the subsidiary legislation is —\n(a)the Income Tax (Concessionary Rate of Tax for Foreign Income of Approved Container Investment Enterprise) Order 2023 (G.N. No. S 33/2023);\n(b)the Income Tax (Exemption of Foreign Income of Approved Shipping Investment Enterprise) Order 2023 (G.N. No. S 36/2023); and\n(c)the Income Tax (Exemption of Foreign Income of Approved International Shipping Enterprises) Order 2018 (G.N. No. S 128/2018)."}}],"pack":"sg-p24","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Assignment of Functions under Section 3A — Maritime and Port Authority of Singapore) Notification 2024","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H1933"] = {"id":"SG-H1933","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S943-2022?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（依第 3A 条转授职能——新加坡金融管理局）公告 2022","en":"Income Tax (Assignment of Functions under Section 3A — Monetary Authority of Singapore) Notification 2022","orig":"Income Tax (Assignment of Functions under Section 3A — Monetary Authority of Singapore) Notification 2022","vi":"Thông báo Thuế thu nhập (Chuyển giao chức năng theo Điều 3A — Cơ quan Tiền tệ Singapore) 2022","th":"ประกาศภาษีเงินได้ (การมอบหมายหน้าที่ตามมาตรา 3A — หน่วยงานการเงินสิงคโปร์) 2022","id":"Pemberitahuan Pajak Penghasilan (Pelimpahan Fungsi menurut Pasal 3A — Otoritas Moneter Singapura) 2022","ms":"Pemberitahuan Cukai Pendapatan (Penyerahan Fungsi menurut Seksyen 3A — Pihak Berkuasa Kewangan Singapura) 2022"},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S943-2022","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H1933-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. This Notification is the Income Tax (Assignment of Functions under Section 3A — Monetary Authority of Singapore) Notification 2022 and comes into operation on 6 December 2022.\n[S 74/2026 wef 23/02/2026]"}},{"id":"SG-H1933-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Assignment of functions"},"text":{"en":"2.—(1) The Minister assigns to the Monetary Authority of Singapore —\n(a)the powers of the Minister under the Act specified in sub‑paragraphs (2) and (3); and\n(b)the powers of the Minister under the subsidiary legislation specified in sub‑paragraph (4).\n(2) For the purposes of sub‑paragraph (1)(a), the powers are —\n(a)the power to grant a waiver of the conditions mentioned in sub‑paragraphs (i) and (ii) of paragraph (c) of the definition of “foreign investor” in section 10(23) of the Act;\n(b)the power to approve an Islamic debt securities arrangement for the purposes of section 10(27) of the Act;\n(ba)the power to approve a company as an approved covered bond company for the purposes of section 10K of the Act;\n[S 74/2026 wef 23/02/2026]\n(c)the powers of approval mentioned in section 13(2), (2A), (2B), (2C), (2D), (2F), (2G), (2H) and (2I) of the Act;\n(d)the power of approval mentioned in the definition of “qualifying debt securities” in section 13(16) of the Act;\n(e)the power of approval mentioned in the definition of “qualifying project debt securities” in section 13(16) of the Act;\n(f)the power to approve a company as an approved securitisation company for the purposes of section 13M of the Act;\n(g)the power to approve a company as an approved company mentioned in section 13O(1) of the Act;\n(ga)the power to specify (other than by regulations) any condition for the exemption from tax of any prescribed income of an approved company mentioned in section 13O(1) of the Act for the purposes of that section;\n[S 74/2026 wef 01/10/2024]\n(gaa)the power to approve a person that manages funds for the purposes of section 13O(1)(b) of the Act;\n[S 74/2026 wef 23/02/2026]\n(gb)the power to approve a limited partnership as an approved limited partnership mentioned in section 13OA(1) of the Act;\n[S 74/2026 wef 01/01/2025]\n(gc)the power to specify (other than by regulations) any condition for the exemption from tax of any prescribed income of a partner of an approved limited partnership mentioned in section 13OA(1) of the Act for the purposes of that section;\n[S 74/2026 wef 01/01/2025]\n(gd)the power to approve a person that manages funds for the purposes of section 13OA(1)(e) of the Act;\n[S 74/2026 wef 23/02/2026]\n(h)the power to approve a person, master fund, feeder fund, 1st tier SPV, 2nd tier SPV, eligible SPV or structure mentioned in section 13U(1)(a) to (d) of the Act;\n(ha)the power to specify (other than by regulations) any condition for the exemption from tax of any prescribed income of a person mentioned in paragraphs (a) to (d) of section 13U(1) of the Act for the purposes of that section;\n[S 74/2026 wef 01/10/2024]\n(i)the power to approve a foreign government‑owned entity or an international organisation mentioned in section 13V(2) of the Act for the purposes of section 13V(1) of the Act;\n[S 74/2026 wef 23/02/2026]\n(j)the power to approve an insurer for the purposes of section 43C(1)(aa) or (c) (in relation to the approval of a captive insurer) of the Act;\n(k)the power of approval mentioned in section 43H(2) of the Act;\n(l)the power to specify requirements for the exemption from tax to apply to any income specified by the Minister derived by a financial sector incentive company mentioned in section 43J(1)(c) of the Act;\n[S 74/2026 wef 23/02/2026]\n(la)the power to specify requirements for the tax rate of 5% to apply to any income specified by the Minister derived by a financial sector incentive company mentioned in section 43J(1B) of the Act;\n[S 74/2026 wef 23/02/2026]\n(lb)the power to approve a company as a financial sector incentive company mentioned in section 43J(1C) of the Act for the purposes of section 43J(1B) of the Act;\n[S 74/2026 wef 23/02/2026]\n(lc)the power to approve a company as a financial sector incentive company mentioned in section 43J(2) of the Act for the purposes of that section;\n[S 74/2026 wef 23/02/2026]\n(ld)the power to provide in the letter of approval of a company for the purposes of section 43J(1)(c) of the Act that the tax exemption does not apply to the company’s income for any year of assessment if a specified requirement is not satisfied, mentioned in section 43J(5) of the Act;\n[S 74/2026 wef 23/02/2026]\n(le)the power to provide in the letter of approval of a company for the purposes of section 43J(1B) of the Act that the tax rate of 5% does not apply to the company’s income for any year of assessment if a specified requirement is not satisfied, mentioned in section 43J(6) of the Act;\n[S 74/2026 wef 23/02/2026]\n(m)the power to approve a company as an approved insurance broker mentioned in subsection (3) of section 43R of the Act for the purposes of that section;\n(n)the power to approve —\n(i)a trustee‑manager of a qualifying registered business trust as an approved trustee‑manager; and\n(ii)a fund management company as an approved fund management company,\nmentioned in subsection (3) of section 43S of the Act for the purposes of that section;\n(o)the power to approve a person mentioned in subsection (3)(c) of section 45I of the Act for the purposes of that section; and\n(p)the power to approve an umbrella VCC mentioned in section 107(15) of the Act for the application of section 13U of the Act and the regulations made thereunder.\n(3) In addition, for the purposes of sub‑paragraph (1)(a), the Minister assigns to the Monetary Authority of Singapore the following powers in relation to section 43C(1)(a), (ab), (b), (c) (in relation to an approved specialised insurer), (d) or (e) of the Act:\n(a)the power to revoke any approval that was granted by the Minister or such person as the Minister may appoint under any of those provisions in force at any time before 6 December 2022;\n(b)the power to add to, vary or revoke any condition of such approval.\n(4) For the purpose of sub‑paragraph (1)(b), the subsidiary legislation are —\n(a)the Income Tax (Exemption of Income of Approved Securitisation Company) Regulations 2008 (G.N. No. S 96/2008);\n(b)the Income Tax (Concessionary Rate of Tax for Income Derived from Managing Qualifying Registered Business Trust or Company) Regulations 2009 (G.N. No. S 155/2009);\n(c)the Income Tax (Exemption of Interest and Other Payments for Economic and Technological Development) (No. 6) Notification 2009 (G.N. No. S 574/2009);\n(ca)the Income Tax (Exemption of Income of Prescribed Persons Arising from Funds Managed by Fund Manager in Singapore) Regulations 2010 (G.N. No. S 6/2010);\n[S 74/2026 wef 23/02/2026]\n(cb)the Income Tax (Exemption of Income of Approved Companies Arising from Funds Managed by Fund Manager in Singapore) Regulations 2010 (G.N. No. S 8/2010);\n[S 74/2026 wef 23/02/2026]\n(d)the Income Tax (Exemption of Certain Income of Prescribed Sovereign Fund Entities and Approved Foreign Government‑Owned Entities) Regulations 2012 (G.N. No. S 50/2012);\n(e)the Income Tax (Exemption of Interest and Other Payments for Economic and Technological Development) Notification 2012 (G.N. No. S 72/2012);\n(f)the Income Tax (Exemption of Interest and Other Payments for Economic and Technological Development) (No. 2) Notification 2012 (G.N. No. S 581/2012);\n(g)the Income Tax (Concessionary Rate of Tax for Financial Sector Incentive Companies) Regulations 2017 (G.N. No. S 239/2017);\n(h)the Income Tax (Exemption and Concessionary Tax Rate for Income from Life Reinsurance Business) Regulations 2017 (G.N. No. S 608/2017);\n(i)the Income Tax (Concessionary Rate of Tax for Approved Insurance Brokers) Regulations 2017 (G.N. No. S 610/2017); and\n(j)the Income Tax (Exemption and Concessionary Tax Rate for Income from General Business) Regulations 2017 (G.N. No. S 614/2017).\n(5) Any power of approval under a provision that is assigned to the Monetary Authority of Singapore under this Notification includes —\n(a)the power to revoke any such approval, including an approval under that provision in force before 6 December 2022 that was granted by the Minister or such person as the Minister may appoint before that date (called in this sub‑paragraph a past approval); and\n(b)(where applicable), the power to —\n(i)impose any condition subject to which an approval may be granted; and\n(ii)add to, vary or revoke any condition of approval (including any condition of a past approval)."}}],"pack":"sg-p24","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Assignment of Functions under Section 3A — Monetary Authority of Singapore) Notification 2022","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H1934"] = {"id":"SG-H1934","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S317-2024?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（依第 3A 条转授职能——新加坡旅游局）公告 2024","en":"Income Tax (Assignment of Functions under Section 3A — Singapore Tourism Board) Notification 2024","orig":"Income Tax (Assignment of Functions under Section 3A — Singapore Tourism Board) Notification 2024","vi":"Thông báo Thuế thu nhập (Chuyển giao chức năng theo Điều 3A — Ủy ban Du lịch Singapore) 2024","th":"ประกาศภาษีเงินได้ (การมอบหมายหน้าที่ตามมาตรา 3A — คณะกรรมการการท่องเที่ยวสิงคโปร์) 2024","id":"Pemberitahuan Pajak Penghasilan (Pelimpahan Fungsi menurut Pasal 3A — Dewan Pariwisata Singapura) 2024","ms":"Pemberitahuan Cukai Pendapatan (Penyerahan Fungsi menurut Seksyen 3A — Lembaga Pelancongan Singapura) 2024"},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S317-2024","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H1934-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. This Notification is the Income Tax (Assignment of Functions under Section 3A — Singapore Tourism Board) Notification 2024 and comes into operation on 12 April 2024."}},{"id":"SG-H1934-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Assignment of functions"},"text":{"en":"2. The Minister assigns to the Singapore Tourism Board the following powers of the Minister under the Act:\n(a)the power to approve a firm or company for the purpose of section 14B(1) of the Act;\n(b)the power to approve a trade fair or trade exhibition held in Singapore for the purpose of section 14B(2)(a)(ii) of the Act;\n(c)the power to approve expenses for the purpose of section 14B(2)(aa) of the Act;\n(d)the power to approve a trade fair or trade exhibition for the purpose of section 14B(2)(ab) of the Act;\n(e)the power to specify the maximum amount of expenditure or any item thereof, mentioned in section 14B(3) of the Act;\n(f)the powers to allow a deduction of an expense and to impose conditions, mentioned in section 14B(5) of the Act."}}],"pack":"sg-p24","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Assignment of Functions under Section 3A — Singapore Tourism Board) Notification 2024","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H1935"] = {"id":"SG-H1935","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S8-2020?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（AT 控股私人有限公司依第 13（12）条享有的豁免）命令 2020","en":"Income Tax (AT Holdings Pte. Ltd. — Section 13(12) Exemption) Order 2020","orig":"Income Tax (AT Holdings Pte. Ltd. — Section 13(12) Exemption) Order 2020","vi":"Lệnh Thuế thu nhập (AT Holdings Pte. Ltd. — Miễn trừ theo Điều 13(12)) 2020","th":"คำสั่งภาษีเงินได้ (AT Holdings Pte. Ltd. — การยกเว้นตามมาตรา 13(12)) 2020","id":"Perintah Pajak Penghasilan (AT Holdings Pte. Ltd. — Pembebasan menurut Pasal 13(12)) 2020","ms":"Perintah Cukai Pendapatan (AT Holdings Pte. Ltd. — Pengecualian menurut Seksyen 13(12)) 2020"},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S8-2020","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H1935-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. This Order is the Income Tax (AT Holdings Pte. Ltd. — Section 13(12) Exemption) Order 2020 and comes into operation on 6 January 2020."}},{"id":"SG-H1935-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2.—(1) Income comprising dividends described in sub‑paragraph (2), that is received in Singapore by AT Holdings Pte. Ltd. (a company incorporated in Singapore) from AT Holdings Europe Co‑operative U.A. (a company incorporated in the Netherlands), is exempt from tax.\n(2) Sub‑paragraph (1) applies to dividends that are derived from dividends received by AT Holdings Europe Co‑operative U.A., that are in turn derived from the profits of any of the following entities:\n(a)AT&C Amstel Holdings B.V.;\n(b)Batys Petroleum LLP;\n(c)Dostyk Gas Terminal LLP;\n(d)Ertys Service LLP;\n(e)Experion Assets Holdings Europe B.V.;\n(f)Kapashagai Resource LLP;\n(g)KazRoslmpex LLP;\n(h)Kazykurt Yug LLP;\n(i)Premium Oil Trans LLP;\n(j)Retail Asset Investment B.V.;\n(k)RTI-ANPZ LLP;\n(l)Standard Petroleum & Co LLP.\n(3) The exemption in sub‑paragraph (1) is subject to the conditions specified in the letters of approval dated 21 June 2018 and 5 November 2019 to AT Holdings Pte. Ltd."}}],"pack":"sg-p24","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (AT Holdings Pte. Ltd. — Section 13(12) Exemption) Order 2020","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H1936"] = {"id":"SG-H1936","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S677-2021?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（AT 控股私人有限公司依第 13（12）条享有的豁免）命令 2021","en":"Income Tax (AT Holdings Pte. Ltd. — Section 13(12) Exemption) Order 2021","orig":"Income Tax (AT Holdings Pte. Ltd. — Section 13(12) Exemption) Order 2021","vi":"Lệnh Thuế thu nhập (AT Holdings Pte. Ltd. — Miễn trừ theo Điều 13(12)) 2021","th":"คำสั่งภาษีเงินได้ (AT Holdings Pte. Ltd. — การยกเว้นตามมาตรา 13(12)) 2021","id":"Perintah Pajak Penghasilan (AT Holdings Pte. Ltd. — Pembebasan menurut Pasal 13(12)) 2021","ms":"Perintah Cukai Pendapatan (AT Holdings Pte. Ltd. — Pengecualian menurut Seksyen 13(12)) 2021"},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S677-2021","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H1936-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. This Order is the Income Tax (AT Holdings Pte. Ltd. — Section 13(12) Exemption) Order 2021 and is deemed to have come into operation on 24 September 2020."}},{"id":"SG-H1936-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2.—(1) Income comprising dividends described in sub‑paragraph (2), that is received in Singapore by AT Holdings Pte. Ltd. (a company incorporated in Singapore) from AT Holdings Europe Co‑operative U.A. (a company incorporated in the Netherlands), is exempt from tax.\n(2) Sub-paragraph (1) applies to dividends that are derived from dividends received by AT Holdings Europe Co‑operative U.A., that are in turn derived from profits of the following entities:\n(a)Retail Asset Investment 2 B.V.;\n(b)Bajes Kwartier B.V.;\n(c)Bajes Kwartier Ontwikkeling C.V.;\n(d)Experion Construction Europe B.V.;\n(e)Experion Participaties B.V.;\n(f)Sterpassage Rijswijk Beheer B.V.;\n(g)Sterpassage Rijswijk C.V.\n(3) The exemption under sub‑paragraph (1) is subject to the conditions specified in the letter of approval dated 24 September 2020 addressed to AT Holdings Pte. Ltd."}}],"pack":"sg-p24","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (AT Holdings Pte. Ltd. — Section 13(12) Exemption) Order 2021","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H1937"] = {"id":"SG-H1937","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S846-2024?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（AT 控股私人有限公司依第 13（12）条享有的豁免）命令 2024","en":"Income Tax (AT Holdings Pte. Ltd. — Section 13(12) Exemption) Order 2024","orig":"Income Tax (AT Holdings Pte. Ltd. — Section 13(12) Exemption) Order 2024","vi":"Lệnh Thuế thu nhập (AT Holdings Pte. Ltd. — Miễn trừ theo Điều 13(12)) 2024","th":"คำสั่งภาษีเงินได้ (AT Holdings Pte. Ltd. — การยกเว้นตามมาตรา 13(12)) 2024","id":"Perintah Pajak Penghasilan (AT Holdings Pte. Ltd. — Pembebasan menurut Pasal 13(12)) 2024","ms":"Perintah Cukai Pendapatan (AT Holdings Pte. Ltd. — Pengecualian menurut Seksyen 13(12)) 2024"},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S846-2024","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H1937-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order is the Income Tax (AT Holdings Pte. Ltd. — Section 13(12) Exemption) Order 2024."}},{"id":"SG-H1937-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2.—(1) Distribution income described in sub‑paragraph (2) that is received in Singapore by AT Holdings Pte. Ltd. (a company incorporated in Singapore) on or after 29 July 2024 from AT Holdings ‑ Europe Coöperatieve U.A. (a cooperative incorporated in the Netherlands), is exempt from tax.\n(2) Sub‑paragraph (1) applies to income received by AT Holdings ‑ Europe Coöperatieve U.A. that is in turn derived from the profits of any of the following:\n(a)Wiebenga Consultants B.V. (a company incorporated in the Netherlands);\n(b)3W Real Estate B.V. (a company incorporated in the Netherlands);\n(c)3W Consultancy B.V. (a company incorporated in the Netherlands);\n(d)Breda Office Investment I Coöperatief U.A. (a cooperative incorporated in the Netherlands);\n(e)Penelope Office Investments B.V. (a company incorporated in the Netherlands);\n(f)Dionysos Office Investments B.V. (a company incorporated in the Netherlands);\n(g)Bajes Kwartier Ontwikkeling H C.V. (a limited partnership registered or formed in the Netherlands);\n(h)Bajes Kwartier Ontwikkeling D C.V. (a limited partnership registered or formed in the Netherlands);\n(i)Bajes Kwartier ESCO Holding B.V. (a company incorporated in the Netherlands);\n(j)A3 Twee B.V. (a company incorporated in the Netherlands);\n(k)Sterpassage Rijswijk I C.V. (a limited partnership registered or formed in the Netherlands);\n(l)Sterpassage Rijswijk Beheer II C.V. (a limited partnership registered or formed in the Netherlands);\n(m)Sterpassage Rijswijk Beheer III C.V. (a limited partnership registered or formed in the Netherlands);\n(n)Sterpassage Rijswijk Beheer IV C.V. (a limited partnership registered or formed in the Netherlands);\n(o)SAS CHARENTON‑BERCY (a company incorporated in France);\n(p)FETEASCA SPÓŁKA Z OGRANICZONĄ ODPOWIEDZIALNOŚCIĄ (a company incorporated in Poland).\n(3) The exemption in sub‑paragraph (1) is subject to the conditions specified in the letter from the Ministry of Finance dated 29 July 2024 and addressed to AT Holdings Pte. Ltd."}}],"pack":"sg-p24","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (AT Holdings Pte. Ltd. — Section 13(12) Exemption) Order 2024","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H1938"] = {"id":"SG-H1938","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S487-2004?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"所得税（自动化设备）规则 2004","en":"Income Tax (Automation Equipment) Rules 2004","orig":"Income Tax (Automation Equipment) Rules 2004","vi":"Quy tắc Thuế thu nhập (Thiết bị tự động hóa) 2004","th":"กฎภาษีเงินได้ (อุปกรณ์ระบบอัตโนมัติ) 2004","id":"Peraturan Pajak Penghasilan (Peralatan Otomasi) 2004","ms":"Kaedah Cukai Pendapatan (Peralatan Automasi) 2004"},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S487-2004","completenessNote":"全文，共 4 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。附表 1 篇以 900000+ 序号随同收录。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H1938-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. These Rules may be cited as the Income Tax (Automation Equipment) Rules 2004 and shall have effect for the year of assessment 2004 and subsequent years of assessment."}},{"id":"SG-H1938-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Automation equipment"},"text":{"en":"2. The automation equipment specified in the Schedule are hereby prescribed for the purposes of the allowances to be made under section 19A(2) of the Act."}},{"id":"SG-H1938-A3","no":3,"noLabel":{"en":"3."},"heading":{"en":"Revocation"},"text":{"en":"3. The Income Tax (Automation Equipment) Rules (R 4) are revoked."}},{"id":"SG-H1938-A900000","no":900000,"noLabel":{"en":"THE SCHEDULE"},"text":{"en":"THE SCHEDULE\nRule 2\nAutomation equipment\n1.Image or graphics processing equipment, including display, facsimile, optical character reader, laser printer, plotter, image setter, digital printing, direct imaging equipment and scanner.\n[S 766/2010 wef 15/12/2010]\n2.Data processing and information technology equipment, including mainframe, minicomputer, microcomputer, desktop, laptop, mobile phone, personal digital assistant and other information technology devices and peripherals.\n[S 766/2010 wef 15/12/2010]\n3.Data communications and networking equipment, including modem, multiplexor, network processor, servers, interface converter, routers, switches, networks, cabling infrastructure, IP telephony systems, broadband connectivity equipment and security and authentication infrastructure.\n[S 766/2010 wef 15/12/2010]\n4.Information technology software including office system software and software used in connection with provision of any office automation service, enterprise resource planning, customer relationship management such as reservations, registration, queue management, ordering, billings and collections, inventory management, record management, knowledge management, human resource and payroll management, financial information and business management such as accounting and assets management, and personnel business travel request, information and management.\n[S 766/2010 wef 15/12/2010]\n5.Computer-aided design system software and computer-aided manufacturing system software.\n6.Surface mount technology machine which is used for the automatic assembly of surface mount devices onto printed circuit boards.\n7.Computer controlled machine for cutting and removal operations with automatic tool change capabilities, including CNC lathes, milling machines, EDM wirecut, machining centers, grinders, presses and laser equipment.\n8.Unmanned automated guided vehicle which is reprogrammable and used for the transfer of goods or materials within a factory or an office.\n9.Co-ordinate measuring machine which is controlled by computer and used for the precise measurement of components for industrial, research or training purposes, including auto in-line vision inspection system and automated testing equipment.\n10.Automated system for storage and retrieval of information, including Radio-Frequency Identification (RFID) system and bar-coding system, and Automated machine for the storage and retrieval of goods or materials, which is controlled by computer and installed with automatic retrieval devices.\n[S 766/2010 wef 15/12/2010]\n11.Flexible manufacturing cells consisting of an integrated manufacturing system comprising at least a computer controlled machine and a robot, including assembly robots, robotic systems and auto-packing lines.\n12.Automated warehousing equipment and software, including Integrated Transport Fleet Management System, Integrated Warehouse Management System (Radio Frequency Terminals) and Very Narrow Aisle (VNA), automatic material handling, collating and binding equipment, Enterprise Resource Planning systems and Materials Resource Planning and Manufacturer Resource Planning software systems.\n13.Automated inspection, testing, packaging and control system for chemicals, pharmaceuticals, medical devices and other automated manufacturing including high speed tabletting machines, high speed packaging machines, such as for blister packaging, infra-red probe for control and inspection, vision devices to check mould function or parts inspection, in-mould transfer parts sorting system and analysis equipment for quality control and assurance.\n14.Injection mould machines used for making plastic, ceramic or metal components in factory production.\n15.Automated chemicals handling equipment, system or line.\n16.Computer-to-plate and computer-to-press systems used in drafting and printing business.\n17.Automated machinery and systems for food processing and packaging or food preservation.\n18.Equipment used in the manufacture (including assembly and testing) of semiconductor wafers or packaged ICs.\n[S 766/2010 wef 15/12/2010]\n19.Automatic equipment used for assembly and testing operations.\n[S 766/2010 wef 15/12/2010]\n20.Automated equipment used in port-related operations.\n21.Automotive navigation systems including telematics system and global positioning system.\n[S 766/2010 wef 15/12/2010]\n22.Automated kitchen equipment for the purpose of food processing.\n[S 766/2010 wef 15/12/2010]\n23.Interactive shopping carts or kiosks.\n[S 766/2010 wef 15/12/2010]\n24.Automated drugs dispensing system for healthcare-related operations.\n[S 766/2010 wef 15/12/2010]\n25.Automated housekeeping equipment including any mattress-lifting equipment for hospitality-related operations.\n[S 766/2010 wef 15/12/2010]\n26.Automated seating systems for convention or exhibition centre, including retractable theatre-style seating.\n[S 766/2010 wef 15/12/2010]\n27.Self-climbing scaffold system.\n[S 766/2010 wef 15/12/2010]\n28.Concrete pumps, whether stationary or mounted on vehicles.\n[S 766/2010 wef 15/12/2010]\n29.Ride-on power float machine.\n[S 766/2010 wef 15/12/2010]"}}],"pack":"sg-p24","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Automation Equipment) Rules 2004","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H1939"] = {"id":"SG-H1939","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S5-2020?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（Azure Sky 投资 10 私人有限公司等——第 13(4) 条豁免）公告 2020","en":"Income Tax (Azure Sky Investments 10 Pte Ltd, etc. — Section 13(4) Exemption) Notification 2020","orig":"Income Tax (Azure Sky Investments 10 Pte Ltd, etc. — Section 13(4) Exemption) Notification 2020","vi":"Thông báo Thuế thu nhập (Azure Sky Investments 10 Pte Ltd, etc. — Miễn trừ theo Điều 13(4)) 2020","th":"ประกาศภาษีเงินได้ (Azure Sky Investments 10 Pte Ltd, etc. — การยกเว้นตามมาตรา 13(4)) 2020","id":"Pemberitahuan Pajak Penghasilan (Azure Sky Investments 10 Pte Ltd, etc. — Pembebasan menurut Pasal 13(4)) 2020","ms":"Pemberitahuan Cukai Pendapatan (Azure Sky Investments 10 Pte Ltd, etc. — Pengecualian menurut Seksyen 13(4)) 2020"},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S5-2020","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H1939-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. This Notification is the Income Tax (Azure Sky Investments 10 Pte Ltd, etc. — Section 13(4) Exemption) Notification 2020 and is deemed to have come into operation on 13 March 2013."}},{"id":"SG-H1939-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2.—(1) The interest and legal fee payable —\n(a)by the borrowers mentioned in the first column of the following table;\n(b)to the respective lenders mentioned in the second column of the table;\n(c)in respect of the respective outstanding loan amounts mentioned in the third column of the table that are or are to be used for the purposes of financing the acquisition of the respective aircraft mentioned in the fourth column of the table;\n(d)under the respective agreements mentioned in the fifth column of the table; and\n(e)that are due and payable during the respective periods mentioned in the sixth column of the table,\nare exempt from tax:\nFirst column\nSecond column\nThird column\nFourth column\nFifth column\nSixth column\nBorrower\nLender\nOutstanding loan amount\nUS$\nAircraft\nAgreement\nPeriod (both dates inclusive)\nAzure Sky Investments 22 Pte Ltd\nGE Japan Corporation\n13,500,000\n“MSN1046”\nSecured aircraft loan agreement dated 13 August 2014\n15 August 2014 to 9 August 2018\nAzure Sky Investments 24 Pte Ltd\nGE Japan Corporation\n35,000,000\n“MSN39820”\nSecured aircraft loan agreement dated 8 August 2014\n12 August 2014 to 12 December 2017\n35,000,000\n“MSN39829”\n16 December 2014 to 12 December 2017\n(2) The interest, legal fee and exposure fee payable —\n(a)by the borrowers mentioned in the first column of the following table;\n(b)to the respective lenders mentioned in the second column of the table;\n(c)in respect of the respective outstanding loan amounts mentioned in the third column of the table that are or are to be used for the purposes of financing the acquisition of the respective aircraft mentioned in the fourth column of the table;\n(d)under the respective agreement or promissory notes mentioned in the fifth column of the table; and\n(e)that are due and payable during the respective periods mentioned in the sixth column of the table,\nare exempt from tax:\nFirst column\nSecond column\nThird column\nFourth column\nFifth column\nSixth column\nBorrower\nLender\nOutstanding loan amount\nUS$\nAircraft\nAgreement or Promissory note\nPeriod (both dates inclusive)\nAzure Sky Investments 10 Pte Ltd\nApple Bank\n40,800,000\n“MSN38687”\nSecured aircraft loan agreement dated 8 March 2013\n13 March 2013 to 12 December 2017\n39,800,000\n“MSN38729”\n19 March 2013 to 12 December 2017\nAzure Sky Investments 14 Pte Ltd\nApple Bank\n40,700,000\n“MSN38690”\nSecured promissory notes dated 3 June 2013\n17 June 2013 to 12 September 2017\n40,700,000\n“MSN38732”\n7 June 2013 to 12 September 2017\n40,300,000\n“MSN38736”\n13 September 2013 to 16 September 2017\n40,400,000\n“MSN38737”\n20 September 2013 to 16 September 2017\n(3) The interest, legal fee, arrangement fee, commitment fee and security trustee fee payable —\n(a)by the borrowers mentioned in the first column of the following table;\n(b)to the respective lenders mentioned in the second column of the table;\n(c)in respect of the respective outstanding loan amounts mentioned in the third column of the table that are or are to be used for the purposes of financing the acquisition of the respective aircraft mentioned in the fourth column of the table;\n(d)under the respective agreements mentioned in the fifth column of the table; and\n(e)that are due and payable during the respective periods mentioned in the sixth column of the table,\nare exempt from tax:\nFirst column\nSecond column\nThird column\nFourth column\nFifth column\nSixth column\nBorrower\nLender\nOutstanding loan amount\nUS$\nAircraft\nAgreement\nPeriod (both dates inclusive)\nAzure Sky Investments 21 Pte Ltd\nGE Japan Corporation\n13,700,000\n“MSN1161”\nSecured aircraft loan agreement dated 18 July 2014\n18 July 2014 to 18 October 2017\n13,700,000\n“MSN1168”\n14 August 2014 to 18 October 2017\n13,700,000\n“MSN1176”\n11 September 2014 to 11 September 2017\n13,700,000\n“MSN1179”\n22 September 2014 to 11 September 2017\n13,700,000\n“MSN1186”\n23 October 2014 to 23 October 2017\n13,700,000\n“MSN1188”\n31 October 2014 to 23 October 2017\n13,700,000\n“MSN1193”\nSecured aircraft loan agreement dated 22 December 2014\n23 December 2014 to 25 September 2017\n13,700,000\n“MSN1220”\n23 December 2014 to 25 September 2017\nAzure Sky Investments 25 Pte Ltd\nSociete Generale, London Branch\n18,000,000\n“MSN1332”\nSecured aircraft loan agreement dated 27 June 2016\n28 June 2016 to 28 June 2018\n18,000,000\n“MSN1336”\nSecured aircraft loan agreement dated 29 June 2016\n30 June 2016 to 28 June 2018\n18,000,000\n“MSN1349”\n15 September 2016 to 15 June 2018\n18,000,000\n“MSN1356”\n4 October 2016 to 4 April 2018\nAzure Sky Investments 27 Pte Ltd\nGE Japan Corporation\n14,400,000\n“MSN1263”\nSecured aircraft loan agreement dated 13 August 2015\n6 October 2015 to 6 July 2018\n14,400,000\n“MSN1271”\n18 August 2015 to 18 August 2018\n14,400,000\n“MSN1275”\n1 October 2015 to 8 June 2018\n14,400,000\n“MSN1282”\n1 October 2015 to 3 July 2018\n14,400,000\n“MSN1290”\n5 November 2015 to 7 August 2018\n14,400,000\n“MSN1291”\n8 December 2015 to 8 June 2018\n(4) The interest, legal fee, exposure fee, arrangement fee, commitment fee and security trustee fee payable —\n(a)by the borrowers mentioned in the first column of the following table;\n(b)to the respective lenders mentioned in the second column of the table;\n(c)in respect of the respective outstanding loan amounts mentioned in the third column of the table that are or are to be used for the purposes of financing the acquisition of the respective aircraft mentioned in the fourth column of the table;\n(d)under the respective agreements or promissory notes mentioned in the fifth column of the table; and\n(e)that are due and payable during the respective periods mentioned in the sixth column of the table,\nare exempt from tax:\nFirst column\nSecond column\nThird column\nFourth column\nFifth column\nSixth column\nBorrower\nLender\nOutstanding loan amount\nUS$\nAircraft\nAgreement or Promissory note\nPeriod (both dates inclusive)\nAzure Sky Investments 16 Pte Ltd\nApple Bank\n37,500,000\n“MSN38739”\nSecured promissory notes dated 28 October 2013\n29 October 2013 to 29 July 2018\n37,800,000\n“MSN38748”\n14 March 2014 to 14 September 2017\n37,900,000\n“MSN39823”\n8 September 2014 to 15 September 2017\n38,900,000\n“MSN39824”\n22 September 2014 to 15 September 2017\nAzure Sky Investments 18 Pte Ltd\nDevelopment Bank of Japan\n16,100,000\n“MSN1081”\nSecured aircraft loan agreement dated 19 March 2014\n19 March 2014 to 5 September 2017\n16,400,000\n“MSN1089”\nSecured aircraft loan agreement dated 18 March 2014\n18 March 2014 to 5 September 2017\n16,400,000\n“MSN1095”\nSecured aircraft loan agreement dated 13 March 2014\n13 March 2014 to 5 September 2017\n16,900,000\n“MSN1123”\n13 March 2014 to 5 September 2017\n16,900,000\n“MSN1130”\nSecured aircraft loan agreement dated 14 March 2014\n14 March 2014 to 5 September 2017\nAzure Sky Investments 18 Pte Ltd\nAeronautic Investments 18 LLC\n13,900,000\n“MSN1081”\nRefinancing promissory note dated 17 December 2015\n17 December 2015 to 5 September 2017\n14,200,000\n“MSN1089”\n17 December 2015 to 5 September 2017\n14,200,000\n“MSN1095”\n17 December 2015 to 5 September 2017\n14,900,000\n“MSN1123”\n17 December 2015 to 5 September 2017\n14,900,000\n“MSN1130”\n17 December 2015 to 5 September 2017\nAzure Sky Investments 26 Pte Ltd\nApple Bank\n38,000,000\n“MSN38304”\nGuaranteed promissory note dated 18 November 2014\n4 December 2014 to 5 June 2018\n(5) The exemptions in sub‑paragraphs (1), (2), (3) and (4) are subject to the conditions specified in the letter of approval dated 7 June 2019 issued by the Ministry of Finance and addressed to Transportation Partners Pte Ltd."}}],"pack":"sg-p24","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Azure Sky Investments 10 Pte Ltd, etc. — Section 13(4) Exemption) Notification 2020","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H1940"] = {"id":"SG-H1940","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S558-2019?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":10,"structureMode":"ARTICLE","title":{"zh":"所得税（保释与个人保证）规则 2019","en":"Income Tax (Bail and Personal Bond) Rules 2019","orig":"Income Tax (Bail and Personal Bond) Rules 2019","vi":"Quy tắc Thuế thu nhập (Bảo lãnh và cam kết cá nhân) 2019","th":"กฎภาษีเงินได้ (การประกันตัวและพันธะส่วนตัว) 2019","id":"Peraturan Pajak Penghasilan (Jaminan dan Ikatan Pribadi) 2019","ms":"Kaedah Cukai Pendapatan (Jaminan dan Ikatan Peribadi) 2019"},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S558-2019","completenessNote":"全文，共 10 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H1940-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. These Rules are the Income Tax (Bail and Personal Bond) Rules 2019 and come into operation on 20 August 2019."}},{"id":"SG-H1940-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Definition"},"text":{"en":"2. In these Rules, unless the context otherwise requires, “released person” means any person who is released on bail or on the person’s personal bond."}},{"id":"SG-H1940-A3","no":3,"noLabel":{"en":"3."},"heading":{"en":"When person may be released on bail or personal bond"},"text":{"en":"3.—(1) When any person is arrested by the Comptroller or a specially authorised officer (called in these Rules an arresting officer) and the person is prepared at any time to give bail in accordance with rule 4, the person must be released on bail by a Magistrate or the arresting officer.\n(2) Instead of taking bail from the person, the Magistrate or arresting officer may release the person if the person signs a personal bond without any surety in accordance with rule 4."}},{"id":"SG-H1940-A4","no":4,"noLabel":{"en":"4."},"heading":{"en":"Bond to be executed"},"text":{"en":"4.—(1) Before any person is released on bail, a bond for such sum of money as a Magistrate or an arresting officer thinks sufficient must be executed by the person and every surety required by the Magistrate or arresting officer to execute the bond.\n(2) Before any person is released on personal bond without any surety, the person must —\n(a)execute a bond for such sum of money as a Magistrate or an arresting officer thinks sufficient; and\n(b)provide such security as may be required by the Magistrate or arresting officer.\n(3) The Magistrate or arresting officer may impose such conditions as he or she thinks necessary before releasing a person on bail or on personal bond.\n(4) Without affecting paragraph (3) and unless the Magistrate or arresting officer specifies otherwise, it is a condition of the bond executed under paragraph (1) or (2) that the released person —\n(a)must provide an address where the released person can be served with any notice, direction or other document under the Act;\n(b)must surrender to custody on the day and at the time and place appointed for the released person to do so;\n(c)must make himself or herself available for investigations or attend court on the day and at the time and place mentioned in the bond, or on such other day or at such other time and place as may be required by the Magistrate or arresting officer, and continue so to attend until otherwise directed by the Magistrate or arresting officer;\n(d)must, if so required by the Magistrate or arresting officer, attend when called upon by any court to answer any charge;\n(e)must not, as long as the bond remains in force, proceed beyond the limits of Singapore without the permission of the Magistrate or arresting officer;\n(f)must not commit any offence while released on bail or on personal bond; and\n(g)must not interfere with any witness or otherwise obstruct the course of justice whether in relation to the released person or any other person.\n(5) Any permission granted under paragraph (4)(e) must be evidenced by an endorsement on the bond specifying the period of time and the place to which the permission extends.\n(6) No such permission may be granted except on the personal application of the released person and in the presence of the released person’s surety, if any."}},{"id":"SG-H1940-A5","no":5,"noLabel":{"en":"5."},"heading":{"en":"Duties of surety"},"text":{"en":"5. Every surety of a person released on bail must —\n(a)ensure that the released person surrenders to custody, makes himself or herself available for investigations or attends court on the day and at the time and place appointed for the released person to do so;\n(b)keep in daily communication with the released person, and lodge a police report within 24 hours of losing contact with the released person; and\n(c)ensure that the released person is within Singapore unless the released person has been permitted by the Magistrate or arresting officer mentioned in rule 4(4)(e) to leave Singapore."}},{"id":"SG-H1940-A6","no":6,"noLabel":{"en":"6."},"heading":{"en":"Amount of bond"},"text":{"en":"6. The amount of every bond executed under rule 4 must be fixed with due regard to the circumstances of the case as being sufficient to secure the attendance of the released person."}},{"id":"SG-H1940-A7","no":7,"noLabel":{"en":"7."},"heading":{"en":"Person to be released"},"text":{"en":"7.—(1) An arrested person must be released by a Magistrate or an arresting officer as soon as the bond has been executed —\n(a)in the case where the person is released on bail, by the person and every surety required by the Magistrate or arresting officer to execute the bond; or\n(b)in the case where the person is released on personal bond, by the person.\n(2) Nothing in these Rules requires the release of any person liable to be arrested for some matter other than that in respect of which the bond was executed."}},{"id":"SG-H1940-A8","no":8,"noLabel":{"en":"8."},"heading":{"en":"Procedure on forfeiture of bond"},"text":{"en":"8.—(1) Section 107 of the Criminal Procedure Code (Cap. 68) applies in a case where a released person bound by a personal bond executed under rule 4(2), fails to surrender to custody, make himself or herself available for investigations, or attend court on the day and at the time and place appointed for him or her to do so.\n(2) Section 107A of the Criminal Procedure Code applies in a case where a released person for whose appearance a bond was executed by the released person and one or more sureties under rule 4(1), fails to surrender to custody, make himself or herself available for investigations, or attend court on the day and at the time and place appointed for him or her to do so."}},{"id":"SG-H1940-A9","no":9,"noLabel":{"en":"9."},"heading":{"en":"Appeal from orders"},"text":{"en":"9. Section 108 of the Criminal Procedure Code applies to any order made under rule 8 by a District Court or Magistrate’s Court."}},{"id":"SG-H1940-A10","no":10,"noLabel":{"en":"10."},"heading":{"en":"Power to direct Magistrate’s Court to exercise powers under rule 8"},"text":{"en":"10. A District Court may direct any Magistrate’s Court to exercise the court’s powers of forfeiture under rule 8 in respect of a bond to appear before the District Court in accordance with section 109 of the Criminal Procedure Code."}}],"pack":"sg-p24","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1749-SG-1200","source":"Income Tax (Bail and Personal Bond) Rules 2019","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H1941"] = {"id":"SG-H1941","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S334-2025?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（宝华钢铁国际私人有限公司——第 13(12) 条豁免）命令 2025","en":"Income Tax (Baohua Steel International Pte. Limited — Section 13(12) Exemption) Order 2025","orig":"Income Tax (Baohua Steel International Pte. Limited — Section 13(12) Exemption) Order 2025","vi":"Lệnh Thuế thu nhập (Baohua Steel International Pte. Limited — Miễn trừ theo Điều 13(12)) 2025","th":"คำสั่งภาษีเงินได้ (Baohua Steel International Pte. Limited — การยกเว้นตามมาตรา 13(12)) 2025","id":"Perintah Pajak Penghasilan (Baohua Steel International Pte. Limited — Pembebasan menurut Pasal 13(12)) 2025","ms":"Perintah Cukai Pendapatan (Baohua Steel International Pte. Limited — Pengecualian menurut Seksyen 13(12)) 2025"},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S334-2025","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H1941-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order is the Income Tax (Baohua Steel International Pte. Limited — Section 13(12) Exemption) Order 2025."}},{"id":"SG-H1941-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2.—(1) Dividend income received in Singapore by Baohua Steel International Pte. Limited (a company incorporated in Singapore) during the period from 1 July 2022 to 31 July 2022 (both dates inclusive) from Fame Risen Development Limited (a company incorporated in Hong Kong), which is in turn derived from the profits of Rizhao Steel Wire Co., Ltd. (a company incorporated in China), is exempt from tax.\n(2) The exemption in sub‑paragraph (1) is subject to the conditions specified in the letter from the Inland Revenue Authority of Singapore dated 15 May 2025 that is issued on behalf of the Minister for Finance and addressed to EY Corporate Advisors Pte. Ltd."}}],"pack":"sg-p24","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Baohua Steel International Pte. Limited — Section 13(12) Exemption) Order 2025","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
